CREATE TABLE finance_ledger (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,name VARCHAR(256) NOT NULL,base_currency CHAR(3) NOT NULL,archived BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,UNIQUE(owner_id,name)); CREATE TABLE finance_account (id UUID PRIMARY KEY DEFAULT uuid_v7(),ledger_id UUID NOT NULL,owner_id UUID NOT NULL,name VARCHAR(256) NOT NULL,type VARCHAR(32) NOT NULL,currency CHAR(3) NOT NULL,opening_balance NUMERIC(19,4) NOT NULL DEFAULT 0,current_balance NUMERIC(19,4) NOT NULL DEFAULT 0,institution VARCHAR(256),masked_identifier VARCHAR(128),credential_ref VARCHAR(512),archived BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id),UNIQUE(ledger_id,name),CHECK(credential_ref IS NULL OR credential_ref LIKE 'secret://%'));
